/bin/zsh -lc "node --input-type=module <<'EOF'
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import { Garden, presets } from './src/simulation.js';
const html = await readFile('dist/standalone.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*)<\\/script>/)?.[1];
if ("'!script) throw new Error('"'Standalone script missing');
new vm.Script(script);
if ("'!html.includes('"'<title>GPT-6</title>') || "'!html.includes('"'<h1>GPT-6</h1>')) throw new Error('Model titles missing');
const a = new Garden(presets.Balanced), b = new Garden(presets.Balanced);
const samples = [];
for (let i = 0; i < 10000; i++) {
  a.step(.08); b.step(.08);
  if (i % 500 === 499) samples.push(a.counts());
}
if (JSON.stringify(a.history) "'!== JSON.stringify(b.history)) throw new Error('"'Seed is not deterministic');
if ("'!samples.slice(2).every(point => point.blue > 0 && point.red > 0)) throw new Error('"'Balanced garden lost a group');
if (Math.max(...samples.map(point => point.blue)) - Math.min(...samples.map(point => point.blue)) < 20) throw new Error('Blue population did not cycle');
if (Math.max(...samples.map(point => point.red)) - Math.min(...samples.map(point => point.red)) < 10) throw new Error('Red population did not cycle');
const low = new Garden(presets['Low fruit']);
for (let i = 0; i < 5000; i++) low.step(.08);
if (low.counts().blue >= a.counts().blue) throw new Error('Low-fruit garden did not stay smaller');
console.log('Standalone parses; model titles, seeded replay, balanced waves, and low-fruit behavior pass.');
EOF
pnpm check"

